"use strict";

// The two class-definition-time positions that are NOT computed keys, and
// that a nested class inside them therefore genuinely DOES reach at
// module load. Both were already correct before RWF-023 for a direct
// call (see the probe table in FINDINGS.md); what RWF-023 adds is that a
// computed METHOD key on a class nested inside one of them is reached too,
// which follows from the same ancestor walk rather than from a new rule.
const danger = require("./danger");

function key() {
  danger.explode("definition-time-key");
  return "x";
}

class StaticFieldHost {
  // A STATIC field initializer runs during class definition, so `Inner`
  // really is defined at module load and its key really does run.
  static inner = class Inner {
    [key()]() {}
  };
}

class StaticBlockHost {
  // A static block runs during class definition for the same reason.
  static {
    class Inner {
      [key()]() {}
    }
    this.inner = Inner;
  }
}

module.exports = { StaticFieldHost, StaticBlockHost };
